INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Hungary';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & standard', '[["RTIR data format", "NAV''s own XML schema, submitted via the Online Szamla API -- the underlying invoice document format is not mandated"], ["Energy/water e-invoices (from Jul 2025)", "No specific format prescribed -- any format and transmission method NAV accepts qualifies"], ["B2G", "EN 16931, the European Standard on e-invoicing, as in every EU member state"], ["Legal basis", "VAT Act (Act CXXVII of 2007) and its RTIR implementing decrees; the energy/water mandate sits in separate sector legislation"]]', 'Don''t confuse RTIR''s mandatory XML data submission with a requirement to issue the invoice itself in that format -- outside the energy/water sector, a Hungarian business can still send a paper or PDF invoice and remain fully RTIR-compliant.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Hungary';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Identifiers & registration', '[["Taxpayer registration", "Hungarian VAT/tax number, registered with NAV"], ["RTIR technical connection", "Online Szamla portal (onlineszamla.nav.gov.hu) -- direct API integration or manual web upload"], ["Governing body", "Nemzeti Ado- es Vamhivatal (NAV) -- National Tax and Customs Administration"], ["Foreign VAT-registered businesses", "In scope for RTIR on the same basis as domestic taxpayers once VAT-registered in Hungary"]]', 'Most invoicing/accounting software used in Hungary has RTIR reporting built in -- confirm yours actually submits automatically rather than relying on manual upload, given how tight the software-invoice deadline is.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Hungary';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Mandatory content', '[["RTIR data fields", "Issuer/buyer tax numbers, invoice number, dates, itemized VAT breakdown, net and gross amounts"], ["Software invoices", "Reported immediately, without human intervention"], ["Manual/paper invoices", "5 calendar days (VAT HUF 100,000-500,000) or 1 calendar day (VAT above HUF 500,000) -- the original 2018 thresholds still shape manual-invoice deadlines even though the reporting-scope threshold itself was removed in 2020"], ["Retention", "8 years for invoices and RTIR submission responses"]]', 'The manual-invoice deadline tiers are a legacy of the original 2018 threshold design -- worth knowing even though every invoice, regardless of value, must now be reported.', NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 0, 'pills' FROM countries WHERE name_en = 'Hungary';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'The issue-then-report flow', 'Outside the energy/water sector, a Hungarian invoice moves through this sequence -- note RTIR reports the invoice''s DATA, not the document itself:', 'The invoice is legally valid on issuance regardless of format -- NAV is not asked to clear or approve it first, unlike the clearance-model mandates covered elsewhere in this tracker (Colombia, Argentina, Jordan). Only for energy/water B2B supplies (from July 2025) must the invoice document itself actually be electronic.');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 0, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Invoice issued to buyer -- paper, PDF, or electronic, all legally valid outside energy/water B2B');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 1, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Invoice data reported to NAV via Online Szamla -- immediately for software invoices');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 2, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'NAV cross-checks reported invoice data against filed VAT returns');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 3, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'From Sep 2026: underlying receipt data separately reported, same real-time principle');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Hungary';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s actually mandatory today, by layer', '[["RTIR data reporting", "Essentially all VAT-registered businesses -- domestic B2B, B2C, export, intra-Community (since 2021)"], ["E-invoice issuance", "Electricity, natural gas, and water utility suppliers only, B2B supplies to non-private customers (since Jul 2025)"], ["Receipt-data reporting", "All businesses, from 1 September 2026"], ["General domestic B2B e-invoicing", "Not mandatory -- proposed in a November 2025 consultation, no enacted date"]]', 'It''s worth being precise about which layer applies to you: nearly every Hungarian business already reports under RTIR, but very few are yet required to actually issue an e-invoice.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Hungary';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'The proposed comprehensive framework (not yet law)', '[["Status", "Public consultation opened Nov 2025, updated concept paper published 31 Mar 2026"], ["Proposed scope", "Domestic B2B, intra-EU B2B, and B2G"], ["Proposed format", "Unified XML compliant with EN 16931"], ["Proposed buyer-side reporting", "Domestic buyers would report received invoices within 5 days"]]', 'Treat every detail here as a proposal, not a commitment -- NAV''s own consultation makes clear the final shape and date are still open.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Hungary';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '💰 HUF 500,000 per RTIR reporting failure', NULL, NULL, 'Businesses face fines of up to HUF 500,000 per invoice not reported, reported late, incompletely, incorrectly, or untruthfully through RTIR. Because RTIR''s scope is now near-universal, this is the penalty exposure that applies to almost every Hungarian VAT-registered business, not a narrow edge case.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Hungary';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📋 HUF 300,000 for ignoring a NAV clarification request', NULL, NULL, 'Since 1 January 2025, failing to respond to a NAV clarification request about a reported invoice within 15 days carries a separate HUF 300,000 fine -- a newer, procedural penalty layered on top of the core RTIR reporting fine above.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Hungary';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🗓 A regime built up in layers, not one mandate date', NULL, NULL, 'Hungary''s history moved in distinct steps, each changing a different thing: RTIR''s launch (2018) and two scope expansions (2020, 2021) built a near-universal data-reporting duty; the 2025 energy/water rule added a narrow but real e-invoicing issuance mandate; 2026 extends reporting to receipts; and a comprehensive B2B/B2G framework remains a live proposal rather than a fixed date. Track which layer any given deadline actually changes before assuming it applies to your business.');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Hungary';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Invoice not reported, reported late, incompletely, incorrectly, or untruthfully via RTIR', 'Up to HUF 500,000 per invoice', '—');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Hungary';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Failure to respond to a NAV clarification request within 15 days (from 1 Jan 2025)', 'HUF 300,000', '—');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Hungary';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your RTIR reporting is fully automated and covers every invoice type', 'RTIR now covers domestic B2B, B2C, export, and intra-Community invoices with no value threshold -- confirm your invoicing/accounting software reports all of them immediately, not just a subset.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Hungary';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'If you supply electricity, gas, or water to Hungarian businesses, move to genuine e-invoicing', 'Since 1 July 2025, B2B supplies in this sector require an actual electronic invoice, not just RTIR-reported data -- confirm your invoicing process has made this switch.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Hungary';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Prepare for receipt-data reporting ahead of 1 September 2026', 'Confirm whether your point-of-sale setup already uses a connected cash register or e-cash register -- if not, plan for 3-day manual receipt reporting now and the full e-cash-register transition by 1 July 2028.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Hungary';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Watch NAV''s comprehensive e-invoicing consultation for a future domestic B2B mandate', 'The November 2025 consultation and March 2026 concept paper propose unified EN 16931 XML invoicing and buyer-side reporting -- no enacted date yet, but worth tracking given how far RTIR''s reporting infrastructure already reaches.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Hungary';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Prepare for the confirmed 2030 EU cross-border floor regardless', 'Every business doing intra-EU B2B trade needs EN 16931 e-invoicing and digital reporting capability from 1 July 2030 -- this date is fixed by EU directive, not Hungarian discretion.');
