INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'NAV — Online Szamla (real-time invoice reporting)');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://nav.gov.hu/', 1 FROM countries WHERE name_en = 'Hungary';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'Nemzeti Ado- es Vamhivatal (NAV) — National Tax and Customs Administration');
